param([switch]$PassThru)
$ErrorActionPreference='Stop';$projectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;. (Join-Path $PSScriptRoot 'resolve-enterprise-powershell.ps1');$runtime=Get-EnterprisePowerShellCommand;$stamp=(Get-Date).ToString('yyyyMMddHHmmssfff');$memoryId="memory-os-$stamp";$taskId="memory-os-task-$stamp";$grantId="memory-os-grant-$stamp";$traceId="memory-os-trace-$stamp";$recordPath=Join-Path $projectRoot ".qianlima/run-traces/enterprise-memory/records/$memoryId.json";$grantPath=Join-Path $projectRoot ".qianlima/run-traces/delegation-grants/$grantId.json"
function Invoke-Child([string]$Script,[string[]]$Arguments){$raw=@(& $runtime -NoProfile -File $Script @Arguments 2>&1);[pscustomobject]@{code=$LASTEXITCODE;text=(($raw|ForEach-Object{$_.ToString()})-join"`n")}};function Add-Case($Cases,[string]$Name,[bool]$Passed){$Cases.Add([pscustomobject]@{name=$Name;passed=$Passed})};$cases=[System.Collections.Generic.List[object]]::new();$creator=Join-Path $PSScriptRoot 'new-enterprise-memory-record.ps1';$queue=Join-Path $PSScriptRoot 'new-enterprise-memory-ingest-job.ps1';$planner=Join-Path $PSScriptRoot 'new-enterprise-memory-query-plan.ps1'
$created=Invoke-Child $creator @('-MemoryId',$memoryId,'-MemoryType','knowledge','-MemoryLayer','world_model','-CubeId','cube-project-a','-ContentRef','memory://sanitized/world-model-a','-Scope','project.a','-SourceRefs','document://project-a/source-v1','-Confidence','0.8','-ExpiresAt',([DateTime]::UtcNow.AddHours(2).ToString('o')),'-Visibility','task_bound','-TenantId','tenant-a','-OrganizationId','org-a','-ProjectId','project-a','-RoleId','analyst','-Classification','internal_sanitized','-RecordVersion','v1','-OwnerId','owner-a','-AuditChainRef','receipt://memory-os/audit','-ActorId','owner-a','-AgentId','source-agent','-AgentVersion','v1','-TaskId',$taskId,'-GrantId',$grantId,'-TraceId',$traceId,'-OutputPath',$recordPath,'-PassThru');Add-Case $cases 'cube_record_has_required_lineage' ($created.code-eq0-and(Get-Content -LiteralPath $recordPath -Raw -Encoding UTF8)-match'"memory_layer"\s*:\s*"world_model"'-and(Get-Content -LiteralPath $recordPath -Raw -Encoding UTF8)-match'"audit_chain_ref"')
$queued=Invoke-Child $queue @('-MemoryPath',$recordPath,'-IdempotencyKey','source-v1','-RequestedBy','source-agent','-PassThru');$queuedAgain=Invoke-Child $queue @('-MemoryPath',$recordPath,'-IdempotencyKey','source-v1','-RequestedBy','source-agent','-PassThru');Add-Case $cases 'async_ingest_is_reference_only_and_idempotent' ($queued.code-eq0-and$queued.text-match'"interaction_blocked"\s*:\s*false'-and$queuedAgain.code-eq0-and$queuedAgain.text-match'"duplicate_suppressed"\s*:\s*true')
$grant=[ordered]@{grant_id=$grantId;tenant_id='tenant-a';organization_id='org-a';project_id='project-a';role_id='analyst';agent_id='query-agent';task_id=$taskId;trace_id=$traceId;data_refs=@('memory-cube://cube-project-a');allowed_tools=@('query_memory');allowed_data_classifications=@('internal_sanitized');expires_at=[DateTime]::UtcNow.AddMinutes(10).ToString('o');status='issued'};New-Item -ItemType Directory -Path (Split-Path -Parent $grantPath) -Force|Out-Null;[IO.File]::WriteAllText($grantPath,($grant|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false));$plan=Invoke-Child $planner @('-GrantPath',$grantPath,'-CubeId','cube-project-a','-TenantId','tenant-a','-OrganizationId','org-a','-ProjectId','project-a','-RoleId','analyst','-MemoryLayers','trajectory;strategy;world_model;skill','-QueryText','approved project policy','-MaxItems','5','-PassThru');Add-Case $cases 'hybrid_plan_filters_scope_before_similarity' ($plan.code-eq0-and$plan.text-match'"scope_filter_precedes_similarity"\s*:\s*true'-and$plan.text-match'fts5_recall'-and$plan.text-match'vector_recall'-and$plan.text-match'temporal_recall'-and$plan.text-match'rerank'-and$plan.text-match'"query_text_stored"\s*:\s*false')
$crossOrg=Invoke-Child $planner @('-GrantPath',$grantPath,'-CubeId','cube-project-a','-TenantId','tenant-a','-OrganizationId','org-b','-ProjectId','project-a','-RoleId','analyst','-MemoryLayers','strategy','-QueryText','blocked','-PassThru');Add-Case $cases 'cross_organization_cube_query_is_denied' ($crossOrg.code-ne0-and$crossOrg.text-match'organization_mismatch');$failed=@($cases|Where-Object{-not$_.passed});$out=[pscustomobject]@{passed=($failed.Count-eq0);cases=@($cases);retrieval_executed=$false;processes_started=$false;listeners_opened=$false;external_calls=$false;business_write=$false};if($PassThru){$out|ConvertTo-Json -Depth 10}else{$cases|Format-Table -AutoSize};if($failed.Count){throw('Enterprise Memory OS regression failed: '+(($failed.name)-join', '))}
